-- 0166: construction arcs for إِلَٰه — 11 arcs, all 147 Qurʾānic uses placed (incl. آلِهَة, إِلَٰهَيْن).
-- construction arcs for إِلَٰه — model كشف; every example checked in the muṣḥaf, every lemma in AL, every count against its verses.
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:la_illa', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'لَا إِلَٰهَ إِلَّا + هُوَ / أَنَا / أَنتَ / اللَّهُ', 'لا', 0, 37, '["2:163", "2:255", "3:2", "3:6", "3:18", "4:87", "6:102", "6:106", "7:158", "9:31", "9:129", "10:90", "11:14", "13:30", "16:2", "20:8", "20:14", "20:98", "21:25", "21:87", "23:116", "27:26", "28:70", "28:88", "35:3", "37:35", "39:6", "40:3", "40:62", "40:65", "44:8", "47:19", "59:22", "59:23", "64:13", "73:9"]', 'إلهٌ = معبودٌ ← نفيُ جنسِ المعبودِ كلِّه بـ«لا» ← ثم إثباتُه لله وحدَه بـ«إلّا»', 'a god = one who is worshipped → no god at all → except Him', 'لا here wipes out the whole kind: not one god of any sort. إلّا then gives the one exception, and it is always God (هُوَ, أَنَا, أَنتَ, اللَّهُ; in 10:90 Pharaoh, drowning, says "except the One the Children of Israel believe in"). The word "exists" is left unsaid, because every hearer knows the point is to deny the thing itself (Ibn ʿĀshūr at 2:163, p.75). al-Zamakhsharī at 2:163: it fixes oneness by denying every other and affirming Him. al-Rāghib (p.82): الإله is the one worshipped.', NULL, '[{"kind": "sense", "label": "except_him", "refs": ["2:163", "2:255", "3:2", "3:6", "3:18", "4:87", "6:102", "6:106", "7:158", "9:31", "9:129", "11:14", "13:30", "20:8", "20:98", "23:116", "27:26", "28:70", "28:88", "35:3", "39:6", "40:3", "40:62", "40:65", "44:8", "59:22", "59:23", "64:13", "73:9"], "note_en": "إِلَّا هُوَ"}, {"kind": "sense", "label": "except_me", "refs": ["16:2", "20:14", "21:25"], "note_en": "إِلَّآ أَنَا — God speaking"}, {"kind": "sense", "label": "except_you", "refs": ["21:87"], "note_en": "إِلَّآ أَنتَ — Jonah calling to God"}, {"kind": "sense", "label": "except_allah", "refs": ["37:35", "47:19"], "note_en": "إِلَّا ٱللَّهُ"}, {"kind": "sense", "label": "except_the_one", "refs": ["10:90"], "note_en": "إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ — Pharaoh at the drowning"}]', '["lex:raghib_mufradat:blk_mfr_4fbd70352e93832c", "lex:lane_lexicon:blk_lane_b8821100e19ef6c5", "lex:fayyumi_misbah_munir:blk_msb_8c9a9e5905c13374", "tafsir:ibn_ashur:2:163", "tafsir:zamakhshari:2:163", "tafsir:ibn_ashur:2:255"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:ma_min', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'مَا … مِنْ إِلَٰهٍ + غَيْرُهُ / إِلَّا اللَّهُ', 'من', 0, 14, '["3:62", "5:73", "7:59", "7:65", "7:73", "7:85", "11:50", "11:61", "11:84", "23:23", "23:32", "23:91", "28:38", "38:65"]', 'إلهٌ = معبودٌ ← نفيٌ يستغرقُ كلَّ إلهٍ بـ«مِن» ← غيرُه / إلّا اللهُ', 'a god → not one single god, of any kind → other than Him', 'مِن after a "no" is extra in grammar but not in meaning: it makes the denial cover every god, like the لا of the last arc (al-Zamakhsharī at 3:62; Ibn ʿĀshūr at 3:62, p.267: it makes plain the whole kind is denied; al-Ālūsī: مِن زائدة للتأكيد). It is the opening call of Noah, Hūd, Ṣāliḥ and Shuʿayb: اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ. غَيْرُهُ was also read غَيْرِهِ and غَيْرَهُ — al-Zamakhsharī at 7:59: by the place of إِلَٰه, by its word, or as "except Him". Pharaoh turns the formula round in 28:38: مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِي.', NULL, '[{"kind": "sense", "label": "other_than_him", "refs": ["7:59", "7:65", "7:73", "7:85", "11:50", "11:61", "11:84", "23:23", "23:32"], "note_en": "مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ — the messengers'' call"}, {"kind": "sense", "label": "except", "refs": ["3:62", "5:73", "38:65"], "note_en": "وَمَا مِنْ إِلَٰهٍ إِلَّا … — answer to the Trinity and to many gods"}, {"kind": "sense", "label": "with_him", "refs": ["23:91"], "note_en": "وَمَا كَانَ مَعَهُ مِنْ إِلَٰهٍ"}, {"kind": "sense", "label": "other_than_me", "refs": ["28:38"], "note_en": "مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِي — Pharaoh"}]', '["tafsir:zamakhshari:3:62", "tafsir:ibn_ashur:3:62", "tafsir:alusi:3:62", "tafsir:zamakhshari:7:59", "lex:raghib_mufradat:blk_mfr_4fbd70352e93832c"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:wahid', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'إِلَٰهٌ وَاحِدٌ', NULL, 0, 14, '["2:133", "2:163", "4:171", "5:73", "6:19", "9:31", "14:52", "16:22", "16:51", "18:110", "21:108", "22:34", "38:5", "41:6"]', 'إلهٌ = معبودٌ ← موصوفٌ بـ«واحد» ← فالمقصودُ العدد: واحدٌ لا اثنان', 'a god → one god → the point is the number: one, not two', 'إِلَٰهٌ alone could just mean "a god"; adding وَاحِدٌ makes the number the point. al-Zamakhsharī at 16:51: if you said only إنما هو إله without واحد, it would sound as if you were proving He is a god, not that He is one. Ibn ʿĀshūr at 2:163 (p.75): in Arab speech الإله is just "the one worshipped", which is why they had many; the verse is aimed first at idolaters, who did not know a god can only be one. Mostly the news after إِلَٰهُكُمْ or إِنَّمَا هُوَ; in 38:5 it is the idolaters'' complaint: "has he made the gods one god?"', NULL, '[{"kind": "sense", "label": "your_god_is_one", "refs": ["2:163", "16:22", "18:110", "21:108", "22:34", "41:6"], "note_en": "إِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ — the news of إِلَٰهُكُمْ"}, {"kind": "sense", "label": "he_is_only_one", "refs": ["4:171", "6:19", "14:52", "16:51"], "note_en": "إِنَّمَا (ٱللَّهُ / هُوَ) إِلَٰهٌ وَاحِدٌ"}, {"kind": "sense", "label": "none_but_one", "refs": ["5:73"], "note_en": "وَمَا مِنْ إِلَٰهٍ إِلَّآ إِلَٰهٌ وَاحِدٌ — against \"the third of three\""}, {"kind": "sense", "label": "one_god_worshipped", "refs": ["2:133", "9:31", "38:5"], "note_en": "نَعْبُدُ / لِيَعْبُدُوا / أَجَعَلَ … إِلَٰهًا وَاحِدًا — as an object"}]', '["tafsir:zamakhshari:16:51", "tafsir:ibn_ashur:16:51", "tafsir:ibn_ashur:2:163", "tafsir:zamakhshari:2:163", "lex:raghib_mufradat:blk_mfr_6ead9cd4d2954e06"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:akhar', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'جَعَلَ / دَعَا + مَعَ اللَّهِ + إِلَٰهًا آخَرَ', NULL, 1, 11, '["6:19", "15:96", "17:22", "17:39", "18:14", "23:117", "25:68", "26:213", "28:88", "50:26", "51:51"]', 'إلهٌ = معبودٌ ← إلهٌ آخرُ يُجعَلُ أو يُدعى مع الله ← وهو الشِّرك', 'a god → a second god set up or prayed to beside God → associating partners with Him', 'Always forbidden or blamed: لَا تَجْعَلْ, لَا تَدْعُ, الَّذِي جَعَلَ. مَعَ is a place-word (ẓarf), not a particle: the other god is put next to God, not in His place. 6:19 has the plural (آلِهَةً أُخْرَىٰ); 18:14 says the same with مِن دُونِهِ — "we will never call on any god besides Him". Ibn ʿĀshūr at 17:22 (p.65): leaving this is the first step of anyone who wants the next life. Lisān (p.7028): whatever is taken as worshipped besides Him is an إِلَٰه to the one who takes it.', NULL, '[{"kind": "sense", "label": "set_up", "refs": ["15:96", "17:22", "17:39", "50:26", "51:51"], "note_en": "جَعَلَ مَعَ اللَّهِ إِلَٰهًا آخَرَ"}, {"kind": "sense", "label": "call_on", "refs": ["18:14", "23:117", "25:68", "26:213", "28:88"], "note_en": "دَعَا مَعَ اللَّهِ إِلَٰهًا آخَرَ / مِن دُونِهِ إِلَٰهًا"}, {"kind": "sense", "label": "bear_witness", "refs": ["6:19"], "note_en": "تَشْهَدُونَ أَنَّ مَعَ اللَّهِ آلِهَةً أُخْرَىٰ"}]', '["tafsir:ibn_ashur:17:22", "lex:ibn_manzur_lisan_arab:blk_lsn_48c163db34f928a1", "lex:fayyumi_misbah_munir:blk_msb_1648ac8bb9bb1fe3"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:ittakhadha', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'اتَّخَذَ / جَعَلَ + (مفعول) + إِلَٰهًا / آلِهَةً (± مِنْ دُونِ اللَّهِ)', NULL, 1, 19, '["5:116", "6:74", "7:138", "7:140", "16:51", "18:15", "19:81", "21:21", "21:24", "25:3", "25:43", "26:29", "36:23", "36:74", "37:86", "43:45", "45:23", "46:28"]', 'إلهٌ = معبودٌ ← يُتَّخَذُ الشيءُ إلهًا ← وهو ليس بإله (من دون الله)', 'a god → taking something as a god → when it is not one', 'اتَّخَذَ takes two objects: the thing, and what it is turned into — إِلَٰهًا / آلِهَةً (Ibn ʿĀshūr at 25:43, p.35). This is the lexicons'' own definition of the word: whatever is taken as worshipped besides God is an إِلَٰه to the one who takes it (Lisān p.7028; Lane p.82: "accord. to him who takes it as such"; al-Rāghib p.82: they made إله a name for everything they worshipped). Most add مِن دُونِ اللَّهِ. Special cases: one''s own desire taken as god (25:43, 45:23); "make us a god" (7:138) and "shall I seek you a god other than God?" (7:140); Pharaoh''s threat "if you take a god other than me" (26:29).', NULL, '[{"kind": "sense", "label": "besides_god", "refs": ["5:116", "18:15", "19:81", "21:24", "25:3", "36:23", "36:74", "37:86", "43:45", "46:28"], "note_en": "اتَّخَذُوا مِن دُونِ اللَّهِ آلِهَةً (and جَعَلَ / تُرِيدُونَ … دُونَ اللَّهِ)"}, {"kind": "sense", "label": "taken_plainly", "refs": ["6:74", "16:51", "21:21"], "note_en": "اتَّخَذَ … آلِهَةً / إِلَٰهَيْنِ (without مِن دُونِ)"}, {"kind": "sense", "label": "desire_as_god", "refs": ["25:43", "45:23"], "note_en": "اتَّخَذَ إِلَٰهَهُ هَوَاهُ"}, {"kind": "sense", "label": "asked_for_a_god", "refs": ["7:138", "7:140"], "note_en": "اجْعَل لَّنَا إِلَٰهًا كَمَا لَهُمْ آلِهَةٌ / أَغَيْرَ اللَّهِ أَبْغِيكُمْ إِلَٰهًا"}, {"kind": "sense", "label": "other_than_me", "refs": ["26:29"], "note_en": "لَئِنِ اتَّخَذْتَ إِلَٰهًا غَيْرِي — Pharaoh"}]', '["tafsir:ibn_ashur:25:43", "lex:ibn_manzur_lisan_arab:blk_lsn_48c163db34f928a1", "lex:lane_lexicon:blk_lane_b8821100e19ef6c5", "lex:raghib_mufradat:blk_mfr_5ef38d7e2970f02a", "lex:raghib_mufradat:blk_mfr_1bb088d1f17cdc92"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:question', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'أَإِلَٰهٌ مَعَ اللَّهِ / مَنْ إِلَٰهٌ غَيْرُ اللَّهِ / أَمْ لَهُمْ إِلَٰهٌ', NULL, 0, 10, '["6:46", "21:43", "27:60", "27:61", "27:62", "27:63", "27:64", "28:71", "28:72", "52:43"]', 'إلهٌ = معبودٌ ← سؤالٌ إنكاريٌّ عن إلهٍ غيرِ الله ← والجوابُ المفهوم: لا أحد', 'a god → "is there a god beside God?" → the answer is plain: none', 'A question that expects "no": after naming what God alone does, it asks who else could. al-Zamakhsharī at 27:60: أَإِلَٰهٌ مَعَ اللَّهِ means "is something else joined to Him as a partner?"; Ibn ʿĀshūr (p.11): the question denies, and it is the result of the proof just before it. With مَنْ (6:46, 28:71–72) it asks which god other than God would bring it back; with أَمْ (21:43, 52:43) "or do they have a god…?". al-Rāghib (p.82) quotes 21:43 for the plural آلِهَة.', NULL, '[{"kind": "sense", "label": "with_god", "refs": ["27:60", "27:61", "27:62", "27:63", "27:64"], "note_en": "أَإِلَٰهٌ مَعَ اللَّهِ — after each of God''s works"}, {"kind": "sense", "label": "who_other", "refs": ["6:46", "28:71", "28:72"], "note_en": "مَنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِهِ"}, {"kind": "sense", "label": "or_have_they", "refs": ["21:43", "52:43"], "note_en": "أَمْ لَهُمْ إِلَٰهٌ غَيْرُ اللَّهِ / آلِهَةٌ تَمْنَعُهُم"}]', '["tafsir:zamakhshari:27:60", "tafsir:ibn_ashur:27:60", "lex:raghib_mufradat:blk_mfr_6ead9cd4d2954e06"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:law', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'لَوْ كَانَ + (فِيهِمَا / مَعَهُ) + آلِهَةٌ ← لَفَسَدَتَا / إِذًا لَـ…', 'لو', 0, 4, '["17:42", "21:22", "21:99", "23:91"]', 'آلهةٌ ← فرضُ آلهةٍ كثيرةٍ بـ«لو» ← فيلزمُ الفسادُ والتغالب، فهو محال', 'gods → "if there were other gods…" → then ruin and rivalry, so it cannot be', 'A proof from the impossible: suppose more gods, and heaven and earth would be ruined (21:22), or they would look for a way up to the Lord of the Throne (17:42). In 21:22 إِلَّا means "other than" — al-Zamakhsharī: "many gods besides the One who made them". 23:91 has no لَوْ but means it: al-Zamakhsharī says the condition is left out — "if there had been gods with Him" — and إِذًا marks the answer (so too Ibn ʿĀshūr, p.114). 21:99 turns it on the idols: had they been gods, they would not have gone into the Fire.', NULL, '[{"kind": "sense", "label": "if_there_were", "refs": ["17:42", "21:22", "21:99"], "note_en": "لَوْ كَانَ … آلِهَةٌ"}, {"kind": "sense", "label": "then_each_god", "refs": ["23:91"], "note_en": "إِذًا لَّذَهَبَ كُلُّ إِلَٰهٍ — لَوْ understood"}]', '["tafsir:zamakhshari:21:22", "tafsir:ibn_ashur:21:22", "tafsir:zamakhshari:23:91", "tafsir:ibn_ashur:23:91"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:fi', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'إِلَٰهٌ + فِي (السَّمَاءِ / الْأَرْضِ)', 'في', 0, 2, '["43:84"]', 'إلهٌ = معبودٌ ← يتعلّقُ به «في» لأنه بمعنى المعبود ← معبودٌ في السماء ومعبودٌ في الأرض', 'a god → worshipped in a place → the One worshipped in heaven and on earth', 'Here فِي hangs on إِلَٰه itself, because the word carries the sense "worshipped": al-Zamakhsharī at 43:84 — the name is given the sense of "the One worshipped" or "the Owner", so the place-phrase attaches to it. It does not put God inside a place. Ibn ʿĀshūr (p.268): it keeps godhood in heaven and on earth for God alone, against those who made the angels and the idols partners.', NULL, NULL, '["tafsir:zamakhshari:43:84", "tafsir:ibn_ashur:43:84", "tafsir:alusi:43:84", "lex:raghib_mufradat:blk_mfr_4fbd70352e93832c"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:claim', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'إِنِّي إِلَٰهٌ مِنْ دُونِهِ', 'من دون', 0, 1, '["21:29"]', 'إلهٌ = معبودٌ ← دعوى الإلهيّةِ من دون الله ← وجزاؤها جهنّم', 'a god → claiming "I am a god besides Him" → its reward is Hell', 'The only place where someone says of himself إِنِّي إِلَٰهٌ. Ibn ʿĀshūr at 21:29 (p.50): it is said of the angels as a supposition only — they would never say it — and it is aimed at those who claimed godhood for them. مِن دُونِهِ = besides Him, as in the اتَّخَذَ arc.', NULL, NULL, '["tafsir:ibn_ashur:21:29", "lex:ibn_manzur_lisan_arab:blk_lsn_48c163db34f928a1"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:idafa', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'إِلَٰهُ + مضاف إليه (إِلَٰهُكُمْ / إِلَٰهُنَا / إِلَٰهُ النَّاسِ / إِلَٰهُ مُوسَىٰ)', NULL, 0, 18, '["2:133", "2:163", "16:22", "18:110", "20:88", "20:97", "20:98", "21:108", "22:34", "28:38", "29:46", "37:4", "40:37", "41:6", "114:3"]', 'إلهٌ = معبودٌ ← مضافٌ إلى مَن يعبدُه ← معبودُكم / معبودُ الناس', 'a god → the god OF someone → the one they worship', 'Joined to the ones who worship (or should): إِلَٰهُكُمْ, إِلَٰهُنَا, إِلَٰهَ آبَائِكَ, إِلَٰهِ النَّاسِ. Mostly the true God, and then the news is usually "one" (إِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ — وَاحِد is in its own arc). al-Zamakhsharī at 114:3: "Lord of people" and "King of people" can be said of others, but إِلَٰهِ النَّاسِ is God''s alone. The same frame can name a false god from the speaker''s side: the calf, "this is your god" (20:88, 20:97), and Pharaoh mocking "the god of Moses" (28:38, 40:37).', NULL, '[{"kind": "sense", "label": "true_god", "refs": ["2:133", "2:163", "16:22", "18:110", "20:98", "21:108", "22:34", "29:46", "37:4", "41:6", "114:3"], "note_en": "إِلَٰهُكُمْ / إِلَٰهُنَا / إِلَٰهُ النَّاسِ — the true God"}, {"kind": "sense", "label": "the_calf", "refs": ["20:88", "20:97"], "note_en": "هَٰذَا إِلَٰهُكُمْ / إِلَٰهِكَ — the golden calf"}, {"kind": "sense", "label": "god_of_moses", "refs": ["28:38", "40:37"], "note_en": "إِلَٰهِ مُوسَىٰ — Pharaoh mocking"}]', '["tafsir:zamakhshari:114:3", "tafsir:ibn_ashur:114:3", "tafsir:ibn_ashur:2:163", "lex:ibn_manzur_lisan_arab:blk_lsn_48c163db34f928a1", "lex:raghib_mufradat:blk_mfr_4fbd70352e93832c"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:اله:ilah:alihah_idafa', 'اله', 'c88f937fab2a9108ab54922b75', NULL, 'آلِهَةُ + ضمير العابدين (آلِهَتُنَا / آلِهَتُكُمْ / آلِهَتُهُمْ) / الْآلِهَة', NULL, 0, 17, '["7:127", "11:53", "11:54", "11:101", "19:46", "21:36", "21:59", "21:62", "21:68", "25:42", "37:36", "37:91", "38:5", "38:6", "43:58", "46:22", "71:23"]', 'إلهٌ حقُّه ألّا يُجمَع ← جمعوه «آلهة» لاعتقادهم ← آلهتُنا: أصنامُهم', '"god" has no true plural → "gods", because they believed in many → "our gods" = their idols', 'al-Rāghib (p.82): إِلَٰه should not have a plural, since there is no one worshipped but Him; the Arabs made it plural because they believed in many. Lisān (p.7028): الآلِهَة are the idols, named after what their worshippers believed, not what they are. So the plural is nearly always tied to its worshippers — "our gods", "your gods" — mostly in the mouths of idolaters defending them. 7:127 وَآلِهَتَكَ is Pharaoh''s gods; Ibn ʿAbbās read وَإِلَاهَتَكَ, "and your worship" (Lisān).', NULL, '[{"kind": "sense", "label": "in_their_mouths", "refs": ["7:127", "11:53", "11:54", "19:46", "21:36", "21:59", "21:62", "21:68", "25:42", "37:36", "38:5", "38:6", "43:58", "46:22", "71:23"], "note_en": "آلِهَتُنَا / آلِهَتُكُمْ / آلِهَتِي — the worshippers speaking"}, {"kind": "sense", "label": "told_of_them", "refs": ["11:101", "37:91"], "note_en": "آلِهَتُهُمْ — the Qurʾān telling of them"}]', '["lex:raghib_mufradat:blk_mfr_6ead9cd4d2954e06", "lex:ibn_manzur_lisan_arab:blk_lsn_48c163db34f928a1", "lex:ibn_manzur_lisan_arab:blk_lsn_40b7fe3e807401d3", "lex:lane_lexicon:blk_lane_b8821100e19ef6c5"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:40:3:ilah_la_illa', 'ARC:اله:ilah:la_illa', '40:3', 40, 3, 'لَآ إِلَٰهَ إِلَّا هُوَۖ إِلَيۡهِ ٱلۡمَصِيرُ', 'There is no god but Him; to Him is the return.', 'the passage verse: the whole kind denied, then God alone kept', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:255:ilah_la_illa', 'ARC:اله:ilah:la_illa', '2:255', 2, 255, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ', 'God — there is no god but Him, the Ever-Living, who keeps all things going.', 'Ibn ʿĀshūr: the sentence is said to prove oneness', 0, 'tafsir:ibn_ashur:2:255', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:20:14:ilah_la_illa', 'ARC:اله:ilah:la_illa', '20:14', 20, 14, 'إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي', 'I am God; there is no god but Me, so worship Me.', 'God speaks of Himself: إِلَّآ أَنَا', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:21:87:ilah_la_illa', 'ARC:اله:ilah:la_illa', '21:87', 21, 87, 'أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ', 'There is no god but You, glory be to You; I have been one of the wrongdoers.', 'Jonah speaks to God: إِلَّآ أَنتَ', 0, NULL, 4);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:7:59:ilah_ma_min', 'ARC:اله:ilah:ma_min', '7:59', 7, 59, 'يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓ', 'My people, worship God; you have no god other than Him.', 'Noah''s words, repeated by Hūd, Ṣāliḥ and Shuʿayb', 1, 'tafsir:zamakhshari:7:59', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:62:ilah_ma_min', 'ARC:اله:ilah:ma_min', '3:62', 3, 62, 'وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُۚ', 'There is no god at all except God.', 'مِن makes the "no" cover every god', 0, 'tafsir:ibn_ashur:3:62', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:28:38:ilah_ma_min', 'ARC:اله:ilah:ma_min', '28:38', 28, 38, 'مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي', 'I know of no god for you other than me.', 'Pharaoh uses the same words for himself', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:16:51:ilah_wahid', 'ARC:اله:ilah:wahid', '16:51', 16, 51, 'إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ فَإِيَّٰيَ فَٱرۡهَبُونِ', 'He is only one God, so fear Me — Me alone.', 'without وَاحِدٌ it would prove godhood, not oneness', 1, 'tafsir:zamakhshari:16:51', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:163:ilah_wahid', 'ARC:اله:ilah:wahid', '2:163', 2, 163, 'وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ', 'Your God is one God.', 'the news of إِلَٰهُكُمْ', 0, 'tafsir:ibn_ashur:2:163', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:38:5:ilah_wahid', 'ARC:اله:ilah:wahid', '38:5', 38, 5, 'أَجَعَلَ ٱلۡأٓلِهَةَ إِلَٰهٗا وَٰحِدًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عُجَابٞ', 'Has he made the gods into one God? That is a strange thing indeed!', 'the idolaters'' complaint', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:17:22:ilah_akhar', 'ARC:اله:ilah:akhar', '17:22', 17, 22, 'لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومٗا مَّخۡذُولٗا', 'Do not set up another god beside God, or you will end up blamed and abandoned.', 'جَعَلَ: to set up a rival', 1, 'tafsir:ibn_ashur:17:22', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:28:88:ilah_akhar', 'ARC:اله:ilah:akhar', '28:88', 28, 88, 'وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۘ لَآ إِلَٰهَ إِلَّا هُوَۚ', 'Do not call on any other god beside God; there is no god but Him.', 'دَعَا: to pray to a rival', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:18:14:ilah_akhar', 'ARC:اله:ilah:akhar', '18:14', 18, 14, 'لَن نَّدۡعُوَاْ مِن دُونِهِۦٓ إِلَٰهٗاۖ', 'We will never call on any god besides Him.', 'the young men of the Cave; مِن دُونِهِ in place of مَعَ', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:19:81:ilah_ittakhadha', 'ARC:اله:ilah:ittakhadha', '19:81', 19, 81, 'وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لِّيَكُونُواْ لَهُمۡ عِزّٗا', 'They took gods besides God, hoping they would be a strength for them.', 'the usual shape: اتَّخَذَ + مِن دُونِ اللَّهِ + آلِهَةً', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:25:43:ilah_ittakhadha', 'ARC:اله:ilah:ittakhadha', '25:43', 25, 43, 'أَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ', 'Have you seen the one who takes his own desire as his god?', 'two objects; Ibn ʿĀshūr: he worships what he likes, with no proof', 0, 'tafsir:ibn_ashur:25:43', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:7:138:ilah_ittakhadha', 'ARC:اله:ilah:ittakhadha', '7:138', 7, 138, 'قَالُواْ يَٰمُوسَى ٱجۡعَل لَّنَآ إِلَٰهٗا كَمَا لَهُمۡ ءَالِهَةٞۚ', 'They said, "Moses, make us a god, just as they have gods."', 'جَعَلَ in the same role as اتَّخَذَ', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:27:62:ilah_question', 'ARC:اله:ilah:question', '27:62', 27, 62, 'أَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَيَكۡشِفُ ٱلسُّوٓءَ … أَءِلَٰهٞ مَّعَ ٱللَّهِۚ', 'Who answers the desperate when he calls and lifts the harm…? Is there a god beside God?', 'asked after each work only God does', 1, 'tafsir:zamakhshari:27:60', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:28:71:ilah_question', 'ARC:اله:ilah:question', '28:71', 28, 71, 'مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ', 'What god other than God could bring you light?', 'with مَنْ', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:52:43:ilah_question', 'ARC:اله:ilah:question', '52:43', 52, 43, 'أَمۡ لَهُمۡ إِلَٰهٌ غَيۡرُ ٱللَّهِۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ', 'Or do they have a god other than God? Glory be to God, far above what they join with Him.', 'with أَمْ', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:21:22:ilah_law', 'ARC:اله:ilah:law', '21:22', 21, 22, 'لَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ', 'If there had been gods in them other than God, both would have fallen into ruin.', 'إِلَّا = other than', 1, 'tafsir:zamakhshari:21:22', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:23:91:ilah_law', 'ARC:اله:ilah:law', '23:91', 23, 91, 'إِذٗا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضٖۚ', 'Then each god would have gone off with what it created, and some would have risen over others.', 'the لَوْ is understood', 0, 'tafsir:zamakhshari:23:91', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:43:84:ilah_fi', 'ARC:اله:ilah:fi', '43:84', 43, 84, 'وَهُوَ ٱلَّذِي فِي ٱلسَّمَآءِ إِلَٰهٞ وَفِي ٱلۡأَرۡضِ إِلَٰهٞۚ', 'He is the One who is God in heaven and God on earth.', 'فِي attaches to إِلَٰه = "worshipped in"', 1, 'tafsir:zamakhshari:43:84', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:21:29:ilah_claim', 'ARC:اله:ilah:claim', '21:29', 21, 29, 'وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهٞ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ جَهَنَّمَۚ', 'Whoever of them should say, "I am a god besides Him" — We would repay him with Hell.', 'a supposition about the angels', 1, 'tafsir:ibn_ashur:21:29', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:114:3:ilah_idafa', 'ARC:اله:ilah:idafa', '114:3', 114, 3, 'إِلَٰهِ ٱلنَّاسِ', 'the God of people', 'al-Zamakhsharī: said of God alone, so it closes the list', 1, 'tafsir:zamakhshari:114:3', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:29:46:ilah_idafa', 'ARC:اله:ilah:idafa', '29:46', 29, 46, 'وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ', 'Our God and your God is one.', 'to the People of the Book', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:20:88:ilah_idafa', 'ARC:اله:ilah:idafa', '20:88', 20, 88, 'فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ', 'They said, "This is your god and the god of Moses, but he forgot."', 'the same frame, said of the calf', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:11:53:ilah_alihah_idafa', 'ARC:اله:ilah:alihah_idafa', '11:53', 11, 53, 'وَمَا نَحۡنُ بِتَارِكِيٓ ءَالِهَتِنَا عَن قَوۡلِكَ', 'We will not leave our gods just because you say so.', 'Hūd''s people defending "our gods"', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:11:101:ilah_alihah_idafa', 'ARC:اله:ilah:alihah_idafa', '11:101', 11, 101, 'فَمَآ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِي يَدۡعُونَ مِن دُونِ ٱللَّهِ مِن شَيۡءٖ', 'The gods they called on besides God were of no use to them at all.', 'the Qurʾān names them by their worshippers', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:7:127:ilah_alihah_idafa', 'ARC:اله:ilah:alihah_idafa', '7:127', 7, 127, 'وَيَذَرَكَ وَءَالِهَتَكَۚ', 'and leave you and your gods', 'Pharaoh''s gods; also read وَإِلَاهَتَكَ', 0, 'lex:ibn_manzur_lisan_arab:blk_lsn_40b7fe3e807401d3', 3);
